    49			if got.FilePath != "sessions/one.md" || got.StartLine != want.line || got.EndLine != want.line ||
    50				got.SnippetStartLine != want.line || got.SnippetEndLine != want.line || got.FocusLine != want.line {
    51				t.Fatalf("promoted span = %#v, want lines %d", got, want.line)
    52			}
    53			if got.Snippet != want.snippet {
    54				t.Fatalf("promoted snippet = %q, want %q", got.Snippet, want.snippet)
    55			}
    56			if got.Score != results[0].Score {
    57				t.Fatalf("promoted score = %v, want the parent's %v", got.Score, results[0].Score)
    58			}
    59			if !hasSearchSignal(got, proseResolutionSignal) {
    60				t.Fatalf("promoted result is not labelled: %#v", got.Signals)
    61			}
    62			if got.SymbolID != "" || got.SymbolName != "" || got.QualifiedName != "" {
    63				t.Fatalf("promoted result claims the parent's symbol identity: %#v", got)
    64			}
    65		}
    66		if len(results[0].Passages) != 2 {
    67			t.Fatalf("input was mutated: %#v", results[0].Passages)
    68		}
    69	}
