   153	// validateSearchContextBlockBudget enforces the policy above on a finished response.
   154	//
   155	// It is a contract check, not a fitter: by the time it runs, every block has already been sized
   156	// by its own funder. It exists because three separately developed funders each satisfied their
   157	// own ceiling and none of them could see the others — the exact shape of bug that ships as "each
   158	// feature was fine on its branch".
   159	func validateSearchContextBlockBudget(response SearchResponse) error {
   160		stats := response.Stats
   161		// Byte accounting first: a block whose reported cost does not match its serialized size
   162		// can break every check below it without tripping any of them.
   163		cardBytes := 0
   164		if len(response.TypeCard) > 0 {
   165			cardBytes = serializedSearchResultBytes(response.TypeCard)
   166		}
   167		if stats.TypeCardBytes != cardBytes {
   168			return fmt.Errorf("search type card byte accounting mismatch: %d != %d", stats.TypeCardBytes, cardBytes)
   169		}
   170		if cardBytes > searchTypeCardBytes {
   171			return fmt.Errorf("search type card exceeds its allowance: %d > %d", cardBytes, searchTypeCardBytes)
   172		}
   173		signatureBytes := 0
   174		if len(response.SignatureTypes) > 0 {
   175			signatureBytes = serializedSearchResultBytes(response.SignatureTypes)
   176		}
   177		if stats.SignatureTypeBytes != signatureBytes {
   178			return fmt.Errorf("search signature type byte accounting mismatch: %d != %d",
   179				stats.SignatureTypeBytes, signatureBytes)
   180		}
   181		if stats.ContainerMapBytes > searchContextBlockAdditiveCap {
   182			return fmt.Errorf("search container map exceeds its allowance: %d > %d",
   183				stats.ContainerMapBytes, searchContextBlockAdditiveCap)
   184		}
   185		// The three agent-asked blocks are additive like the map, so each one is held to its own cap
   186		// here. Their measured cost per block is the whole reason they are allowed to be additive: a
   187		// warning that cannot fit is a warning that never arrives.
   188		for _, additive := range []struct {
   189			name  string
   190			bytes int
   191			cap   int
   192		}{
   193			// The literal cluster's cap depends on what the block CARRIES, not on what the caller asked
   194			// for: --edit-site-bodies raises it to searchLiteralEditBodyClusterMaxBytes, and the same
   195			// derivation the fitter used is applied here so the two can never disagree.
   196			{
   197				name:  "literal cluster",
   198				bytes: stats.LiteralClusterBytes,
   199				cap:   searchLiteralClusterCap(response.LiteralCluster, searchLiteralClusterMaxBytes),
   200			},
   201			{name: "verify command", bytes: stats.VerifyCommandBytes, cap: searchVerifyCommandMaxBytes + stats.VerifyExplainSuffixBytes},
   202			{name: "closed set", bytes: stats.ClosedSetBytes, cap: searchClosedSetMaxBytes},
   203		} {
   204			if additive.bytes > additive.cap {
   205				return fmt.Errorf("search %s exceeds its allowance: %d > %d",
   206					additive.name, additive.bytes, additive.cap)
   207			}
   208		}
   209		if actual := searchLiteralClusterCost(response.LiteralCluster); stats.LiteralClusterBytes != actual {
   210			return fmt.Errorf("search literal cluster byte accounting mismatch: %d != %d",
   211				stats.LiteralClusterBytes, actual)
   212		}
   213		if actual := searchVerifyCommandCost(response.VerifyCommand); stats.VerifyCommandBytes != actual {
   214			return fmt.Errorf("search verify command byte accounting mismatch: %d != %d",
   215				stats.VerifyCommandBytes, actual)
   216		}
   217		if actual := searchClosedSetCost(response.ClosedSet); stats.ClosedSetBytes != actual {
   218			return fmt.Errorf("search closed set byte accounting mismatch: %d != %d",
   219				stats.ClosedSetBytes, actual)
   220		}
   221		if total := searchContextBlockBytes(stats); stats.ContextBlockBytes != total {
   222			return fmt.Errorf("search context block byte accounting mismatch: %d != %d",
   223				stats.ContextBlockBytes, total)
   224		}
   225		// The ceiling. The container map is excluded by policy (it is the additive block, capped
   226		// above); every other block is funded from inside the ceiling, so their combined cost plus
   227		// the ranking must fit. Checking them one at a time — which is what each funder does on its
   228		// own — passes while the sum overshoots.
   229		if stats.ContextBudgetBytes > 0 {
   230			funded := stats.ResultBytes + stats.TypeCardBytes + stats.SignatureTypeBytes
   231			if funded > stats.ContextBudgetBytes {
   232				return fmt.Errorf("search context exceeds byte budget: %d > %d",
   233					funded, stats.ContextBudgetBytes)
   234			}
   235		}
   236		return nil
   237	}
